<template>
  <div class="admin-shell"><aside class="sidebar"><div class="brand"><span class="mark">⚡</span><strong>Seckill<span>Core</span></strong></div><p class="side-label">管理工作台</p><nav><button v-for="item in navItems" :key="item.key" type="button" :class="{ active: activeNav === item.key }" @click="switchNav(item.key)"><span>{{ item.icon }}</span>{{ item.label }}</button></nav><div class="side-footer"><span class="admin-avatar">A</span><div><b>系统管理员</b><small>管理员账号</small></div></div></aside><main class="main"><header class="topbar"><div><h1>{{ currentNav.label }}</h1><p>{{ currentNav.description }}</p></div><div class="top-actions"><span class="connection"><i></i> API 已配置</span><button class="notice" type="button" title="刷新数据" @click="loadData">↻</button></div></header><section v-if="activeNav === 'overview'" class="stats"><article v-for="stat in stats" :key="stat.label"><span class="stat-icon">{{ stat.icon }}</span><div><small>{{ stat.label }}</small><strong>{{ stat.value }}</strong><em>{{ stat.note }}</em></div></article></section><section class="content-grid"><div class="panel main-panel"><div class="panel-heading"><div><h2>{{ currentNav.tableTitle }}</h2><p>{{ currentNav.tableDescription }}</p></div><button class="primary-button" type="button" @click="loadData">↻ 刷新</button></div><p v-if="errorMessage" class="page-error">{{ errorMessage }} <button type="button" @click="loadData">重新加载</button></p><div v-if="loading" class="loading-state"><i></i><i></i><i></i></div><template v-else-if="activeNav === 'products'"><div class="table-head product-columns"><span>商品名称</span><span>秒杀价</span><span>库存</span><span>状态</span></div><div v-for="item in products" :key="item.id" class="table-row product-columns"><span class="product-name"><i></i>{{ item.productName }}</span><b>¥{{ price(item.seckillPrice || item.price) }}</b><span>{{ item.availableStock ?? '--' }} / {{ item.totalStock ?? '--' }}</span><span class="tag" :class="item.status === 1 ? 'online' : 'offline'">{{ item.status === 1 ? '已上架' : '已下架' }}</span></div><div v-if="!products.length" class="empty-hint">暂无商品数据</div></template><template v-else-if="activeNav === 'activities'"><div class="table-head activity-columns"><span>活动名称</span><span>时间</span><span>剩余库存</span><span>状态</span></div><div v-for="item in activities" :key="item.id" class="table-row activity-columns"><span class="product-name"><i class="activity-dot"></i>{{ item.activityName }}</span><span>{{ formatDate(item.startTime) }}</span><span>{{ item.remainingLimit ?? '--' }} / {{ item.totalLimit ?? '--' }}</span><span class="tag" :class="activityClass(item.status)">{{ activityLabel(item.status) }}</span></div><div v-if="!activities.length" class="empty-hint">暂无活动数据</div></template><template v-else-if="activeNav === 'users'"><div class="table-head user-columns"><span>用户</span><span>联系方式</span><span>注册时间</span><span>状态</span></div><div v-for="item in users" :key="item.id" class="table-row user-columns"><span class="product-name"><i class="user-dot"></i>{{ item.username }}</span><span>{{ item.phone || item.email || '--' }}</span><span>{{ formatDate(item.createTime) }}</span><button class="status-button" :class="item.status === 1 ? 'normal' : 'frozen'" type="button" @click="toggleUser(item)">{{ item.status === 1 ? '正常' : '已冻结' }}</button></div><div v-if="!users.length" class="empty-hint">暂无用户数据</div></template><div v-else class="overview-placeholder"><span>▦</span><b>数据概览已连接</b><small>商品、活动、用户数据会在对应模块中实时展示</small></div></div><div class="panel quick-panel"><div class="panel-heading"><div><h2>快捷入口</h2><p>常用管理功能</p></div></div><button v-for="item in shortcuts" :key="item.key" class="shortcut" type="button" @click="switchNav(item.key)"><span>{{ item.icon }}</span><div><b>{{ item.label }}</b><small>{{ item.desc }}</small></div><strong>›</strong></button><div class="api-note"><i></i><span>当前后端已提供商品、活动、用户读取接口；商品与活动写入接口待接入。</span></div></div></section><Transition name="toast"><div v-if="message" class="toast">{{ message }}</div></Transition></main></div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { getActivities, getProducts, getUsers, updateUserStatus } from './api'

const navItems = [{ key: 'overview', label: '数据概览', icon: '▦', description: '查看平台核心运行数据' }, { key: 'products', label: '商品管理', icon: '◇', description: '查看已上架商品与库存状态' }, { key: 'activities', label: '活动配置', icon: '◷', description: '查看秒杀活动时间与库存' }, { key: 'users', label: '用户管理', icon: '◎', description: '管理平台用户状态' }]
const shortcuts = [{ key: 'products', label: '商品管理', desc: '查看商品与库存', icon: '◇' }, { key: 'activities', label: '活动配置', desc: '查看秒杀场次', icon: '◷' }, { key: 'users', label: '用户管理', desc: '管理用户状态', icon: '◎' }]
const activeNav = ref('overview'); const loading = ref(false); const errorMessage = ref(''); const message = ref(''); const products = ref([]); const activities = ref([]); const users = ref([]); const totals = ref({ products: 0, activities: 0, users: 0 }); let messageTimer
const currentNav = computed(() => navItems.find((item) => item.key === activeNav.value) || navItems[0]); const stats = computed(() => [{ label: '商品总数', value: totals.value.products, note: '来自商品服务', icon: '◇' }, { label: '进行中活动', value: activities.value.filter((item) => item.status === 1).length, note: '实时活动状态', icon: '◷' }, { label: '平台用户数', value: totals.value.users, note: '来自用户服务', icon: '◎' }, { label: '接口状态', value: errorMessage.value ? '异常' : '正常', note: errorMessage.value ? '请检查服务' : '已连接网关', icon: '✓' }])
function pageRecords(result) { return result?.data?.records || [] }
function price(value) { return Number(value || 0).toFixed(2) }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '--' }
function activityLabel(status) { return ({ 0: '未开始', 1: '进行中', 2: '已结束', 3: '已取消' })[status] || '未知' }
function activityClass(status) { return ({ 0: 'soon', 1: 'online', 2: 'offline', 3: 'offline' })[status] || 'offline' }
function switchNav(key) { activeNav.value = key; if (key !== 'overview') loadData() }
function notify(value) { message.value = value; clearTimeout(messageTimer); messageTimer = setTimeout(() => { message.value = '' }, 2400) }
async function loadData() { loading.value = true; errorMessage.value = ''; try { const [productResult, activityResult, userResult] = await Promise.all([getProducts({ page: 1, size: 100 }), getActivities({ page: 1, size: 100 }), getUsers({ page: 1, size: 100 })]); products.value = pageRecords(productResult); activities.value = pageRecords(activityResult); users.value = pageRecords(userResult); totals.value = { products: productResult?.data?.total || products.value.length, activities: activityResult?.data?.total || activities.value.length, users: userResult?.data?.total || users.value.length } } catch (error) { errorMessage.value = error.message } finally { loading.value = false } }
async function toggleUser(user) { const nextStatus = user.status === 1 ? 0 : 1; try { await updateUserStatus(user.id, nextStatus); user.status = nextStatus; notify(nextStatus === 1 ? '用户已解冻' : '用户已冻结') } catch (error) { notify(error.message) } }
onMounted(loadData)
</script>

<style scoped>
