ivity-dot{background:#9bd6bd}.product-name i.user-dot{background:#f5c785}.tag,.status-button{width:max-content;padding:4px 7px;border:0;border-radius:5px;font:inherit;font-size:10px}.tag.online,.status-button.normal{color:#36a976;background:#ebf9f2}.tag.soon{color:#ce9146;background:#fff6e8}.tag.offline,.status-button.frozen{color:#9aa8b7;background:#f1f4f7}.status-button{cursor:pointer}.empty-hint{margin:20px 0 0;color:#b0bbc8;font-size:10px;text-align:center}.loading-state{display:grid;gap:14px}.loading-state i{height:43px;border-radius:7px;background:linear-gradient(100deg,#eef2f7,#f9fafc,#eef2f7);background-size:200% 100%;animation:shine 1.3s infinite}.page-error{margin:0 0 17px;padding:10px 12px;border-radius:8px;color:#b44d4d;font-size:12px;background:#fff2f2}.page-error button{margin-left:7px;padding:0;border:0;color:#c33f3f;text-decoration:underline;background:none;cursor:pointer}.overview-placeholder{display:flex;min-height:260px;align-items:center;justify-content:center;flex-direction:column;gap:10px;color:#8998ab}.overview-placeholder span{font-size:34px;color:#78a8ef}.overview-placeholder b{font-size:14px}.overview-placeholder small{font-size:11px}.shortcut{display:flex;width:100%;padding:15px 0;align-items:center;gap:12px;border:0;border-bottom:1px solid #f0f3f6;text-align:left;background:none;cursor:pointer}.shortcut:last-of-type{border-bottom:0}.shortcut>span{display:grid;width:35px;height:35px;place-items:center;border-radius:9px;color:#4a86ea;background:#edf4ff}.shortcut div{display:flex;flex:1;flex-direction:column;gap:5px}.shortcut b{color:#4c5e77;font-size:12px}.shortcut small{color:#a0adbc;font-size:10px}.shortcut>strong{color:#b1bdcb;font-size:20px;font-weight:400}.api-note{display:flex;margin-top:20px;padding:12px;gap:8px;border-radius:8px;color:#95a3b4;font-size:10px;line-height:1.5;background:#f7f9fc}.api-note i{width:6px;height:6px;flex:0 0 6px;margin-top:4px;border-radius:50%;background:#6fa4ed}.toast{position:fixed;z-index:20;right:35px;bottom:28px;padding:11px 16px;border-radius:8px;color:#fff;font-size:12px;background:#23344e;box-shadow:0 8px 25px rgba(30,48,80,.2)}@keyframes shine{to{background-position:-200% 0}}@media(max-width:900px){.sidebar{width:190px}.main{padding:0 22px 40px}.stats{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}}@media(max-width:560px){.sidebar{width:65px;padding:20px 9px}.brand{padding:0;justify-content:center}.brand strong,.side-label,.side-footer div{display:none}.sidebar nav button{justify-content:center;padding:0}.side-footer{justify-content:center;padding:17px 0 0}.main{padding:0 15px 30px}.stats{grid-template-columns:1fr}.topbar{min-height:100px}.connection{display:none}.table-head,.table-row{font-size:10px}.user-columns{grid-template-columns:1.2fr 1.1fr .75fr}.user-columns span:nth-child(3){display:none}}
</style>
